// 明确新域只存实际执行来源；不会给旧TaskShopOrders1编码追加空字段。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "task_shop_order_estate_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/tasks/task_source_projection.hpp"
namespace hanmo::resident {namespace {
template<class A>Status request(A& a,PrivateShopEstateCancellationRequest& r){a.field("shop_id",r.shop_id);a.field("order_id",r.order_id);a.field("original_proprietor_actor_id",r.original_proprietor_actor_id);a.field("executor_actor_id",r.executor_actor_id);a.field("mandate_fact_id",r.mandate_fact_id);return a.field("death_notice_binding_fact_id",r.death_notice_binding_fact_id);}
template<class A>Status cancellation(A& a,TaskShopOrderEstateCancellation& r){a.field("fact_id",r.fact_id);a.field("task_id",r.task_id);a.field("settlement_fact_id",r.settlement_fact_id);a.field("settlement_id",r.settlement_id);a.field("tick",r.tick);auto checked=a.object("request",[&](auto& child){return request(child,r.request);});if(!checked.ok)return checked;return a.optional("player_receipt",r.player_receipt,[](auto& child,auto& v){child.field("result_id",v.result_id);child.field("request_sequence",v.request_sequence);return child.field("result_revision",v.result_revision);});}
template<class A>Status state(A& a,TaskShopOrderEstateCancellationState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedTaskShopOrderEstateVersion");return dynamic_codec::table(a,"cancellations",s.cancellations,[](auto& child,auto& r){return cancellation(child,r);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("TaskShopOrderEstateTooDeep");if(const auto* fields=v.as<BoundaryValue::Dict>()){if(fields->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderEstateTooLarge");std::set<StableId> seen;for(const auto& row:*fields){if(!seen.insert(row.first).second)return common_failure("DuplicateTaskShopOrderEstateField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* rows=v.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderEstateTooLarge");for(const auto& row:*rows){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Outcome<TaskShopOrderEstateCancellationState> decode_task_shop_order_estate_cancellations(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};TaskShopOrderEstateCancellationState result;dynamic_codec::JsonArchive a(v);r=state(a,result);if(r.ok)r=a.finish();return {r.ok,std::move(result),r.error};}
Status emit_task_shop_order_estate_cancellations_fields(ProjectionWriter&w,const TaskShopOrderEstateCancellationState&v){dynamic_projection::Archive a(w);return state(a,const_cast<TaskShopOrderEstateCancellationState&>(v));}
BoundaryValue encode_task_shop_order_estate_cancellations(const TaskShopOrderEstateCancellationState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_order_estate_cancellations_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status visit_task_shop_order_estate_cancellations_checkpoint(CodecVisitor& a,TaskShopOrderEstateCancellationState& s){return state(a,s);}
Status emit_task_shop_order_estate_fact_fields(ProjectionWriter&w,const TaskShopOrderEstateCancellationState&s,const StableId&id){dynamic_projection::Archive a(w);Status valid;StableId kind;if(const auto*row=s.cancellations.find(id)){valid=cancellation(a,const_cast<TaskShopOrderEstateCancellation&>(*row));kind=task_shop_order_estate_cancelled_kind;}else return common_failure("MissingTaskShopOrderEstateCancellation",id);if(!valid.ok)return valid;w.field("kind",kind);w.text("domain",std::string_view(task_shop_order_estate_module));return w.status();}
Outcome<BoundaryValue> encode_task_shop_order_estate_fact(const TaskShopOrderEstateCancellationState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_order_estate_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
